import{_ as n,C as i,o as e,c as s,a3 as a,b as l,w as o,a as d,E as c,a2 as h}from"./chunks/framework.CDCjIvJ8.js";const E=JSON.parse('{"title":"Socratic tutoring","description":"","frontmatter":{},"headers":[],"relativePath":"flows/tutoring.md","filePath":"flows/tutoring.md","lastUpdated":1789296458000}'),u={name:"flows/tutoring.md"};function p(m,t,g,f,A,y){const r=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="socratic-tutoring" tabindex="-1">Socratic tutoring <a class="header-anchor" href="#socratic-tutoring" aria-label="Permalink to &quot;Socratic tutoring&quot;">​</a></h1><p>The generative side of the platform, and the one place where restraint is the feature.</p><h2 id="the-pedagogical-constraint" tabindex="-1">The pedagogical constraint <a class="header-anchor" href="#the-pedagogical-constraint" aria-label="Permalink to &quot;The pedagogical constraint&quot;">​</a></h2><p>Ask a general-purpose model &quot;what should my termination clause say?&quot; and it writes the clause. The student pastes it in, scores well, and has learned nothing — the cognitive work the exercise exists to produce has been done by the model.</p><p>The tutor is prompted to answer that question with a question:</p><blockquote><p>Which statute governs notice periods for this kind of employment, and what minimum does it set? Look at what your clause currently says about <em>when</em> either party may end the agreement.</p></blockquote><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2>',7)),(e(),l(h,null,{default:o(()=>[c(r,{id:"mermaid-23",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20S%20as%20Student%0A%20%20%20%20participant%20API%0A%20%20%20%20participant%20CS%20as%20Chat%20service%0A%20%20%20%20participant%20M%20as%20Memory%0A%20%20%20%20participant%20R%20as%20Retrieval%0A%20%20%20%20participant%20LLM%20as%20Groq%0A%0A%20%20%20%20S-%3E%3EAPI%3A%20POST%20%2Fconversations%20%7Btitle%7D%0A%20%20%20%20API-%3E%3ECS%3A%20create%20thread%0A%20%20%20%20CS--%3E%3ES%3A%20conversation_id%0A%0A%20%20%20%20S-%3E%3EAPI%3A%20POST%20%2Fchat%2Fsend%20%7Bconversation_id%2C%20message%2C%3Cbr%2F%3Edocument_type%2C%20draft_id%7D%0A%20%20%20%20API-%3E%3EAPI%3A%20rate%20limit%20(LLM%20scope)%20%2B%20token%20budget%0A%0A%20%20%20%20CS-%3E%3EM%3A%20recent%20turns%20for%20this%20conversation%0A%20%20%20%20CS-%3E%3EM%3A%20learning%20memory%20for%20this%20student%0A%20%20%20%20CS-%3E%3EM%3A%20document%20memory%20for%20this%20draft%0A%20%20%20%20Note%20over%20CS%2CM%3A%20Three%20tiers%3A%20what%20was%20just%20said%2C%3Cbr%2F%3Ewhat%20this%20student%20struggles%20with%2C%3Cbr%2F%3Ewhat%20this%20draft%20contains.%0A%0A%20%20%20%20CS-%3E%3ER%3A%20retrieve%20precedent%20for%20the%20question%0A%20%20%20%20R--%3E%3ECS%3A%20passages%20%2B%20citations%0A%0A%20%20%20%20CS-%3E%3ELLM%3A%20Socratic%20system%20prompt%3Cbr%2F%3E%2B%20memory%20%2B%20evidence%20%2B%20question%0A%20%20%20%20LLM--%3E%3ECS%3A%20guiding%20response%0A%0A%20%20%20%20CS-%3E%3EM%3A%20persist%20the%20turn%0A%20%20%20%20CS--%3E%3ES%3A%20answer%20%2B%20cited%20sources%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="memory-tiers" tabindex="-1">Memory tiers <a class="header-anchor" href="#memory-tiers" aria-label="Permalink to &quot;Memory tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tier</th><th style="text-align:left;">Holds</th><th style="text-align:left;">Why separate</th></tr></thead><tbody><tr><td style="text-align:left;">Conversation</td><td style="text-align:left;">Recent turns</td><td style="text-align:left;">Immediate coherence</td></tr><tr><td style="text-align:left;">Learning</td><td style="text-align:left;">Recurring weak skills</td><td style="text-align:left;">Lets the tutor connect today&#39;s question to a pattern</td></tr><tr><td style="text-align:left;">Document</td><td style="text-align:left;">Summary of the draft under discussion</td><td style="text-align:left;">Avoids re-sending the whole draft on every turn</td></tr></tbody></table><p>Summarising the document rather than re-sending it keeps prompt tokens roughly flat across a long conversation. Prompt-token growth is charted separately on the <a href="/DraftForge-2/operations/observability">cost dashboard</a> for exactly this reason.</p><h2 id="it-cannot-touch-a-score" tabindex="-1">It cannot touch a score <a class="header-anchor" href="#it-cannot-touch-a-score" aria-label="Permalink to &quot;It cannot touch a score&quot;">​</a></h2><p>The tutor, the drafting assistant and the evaluation explainer all read evaluations for context and none can write one. Enforced structurally: <code>app/ai/evaluation/</code> imports nothing from <code>app/ai/llm/</code>.</p><h2 id="cost-controls" tabindex="-1">Cost controls <a class="header-anchor" href="#cost-controls" aria-label="Permalink to &quot;Cost controls&quot;">​</a></h2><p>Every generative endpoint carries:</p><ul><li><code>LimitScope.LLM</code> — 10/min and 300/day per user by default.</li><li>A per-user <strong>daily token budget</strong>, because request counts cannot bound spend.</li><li>An outbound timeout, so a hung provider does not hold a worker.</li></ul><p>Token counts are recorded per call, split into prompt and completion.</p><div class="warning custom-block"><p class="custom-block-title">Known gap</p><p>Prompt-injection defences are not yet implemented. A student can place instructions inside a draft that the tutor will read as part of its context. The realistic impact is a student coaxing the tutor into writing their clause — a pedagogical failure rather than a data breach, since the tutor has no privileged access and cannot alter a mark. Delimiter isolation and instruction hierarchy are the planned mitigations.</p></div>',10))])}const S=n(u,[["render",p]]);export{E as __pageData,S as default};
